const body = $input.first().json.body || $input.first().json;

const booking_id      = body.booking_id || '';
const tenant_id       = parseInt(body.tenant_id || $input.first().json.headers?.['x-tenant-id'] || '0');
const cancelled_by    = body.cancelled_by || 'staff';
const reason          = body.cancellation_reason || body.reason || '';
const refund_override = body.refund_amount != null ? parseFloat(body.refund_amount) : null;
const jwt             = body.jwt || '';

if (!booking_id) throw new Error('booking_id is required');
if (!tenant_id)  throw new Error('tenant_id is required');

const ref = 'CANC-' + Math.floor(100000 + Math.random() * 900000);

return [{ json: { booking_id, tenant_id, cancelled_by, reason, refund_override, cancellation_ref: ref, jwt } }];

const input     = $('Extract & Validate').first().json;
const booking   = $('DB: Get Booking').first().json;
const policyRows= $input.all().map(r => r.json);

if (!booking || !booking.id) throw new Error('Booking not found or wrong tenant');

const getSetting = (key, def) => {
  const r = policyRows.find(p => p.key === key);
  return r ? (parseFloat(r.value) || def) : def;
};
const fullDays = getSetting('cancel_full_refund_days',    14);
const partDays = getSetting('cancel_partial_refund_days',  7);
const partPct  = getSetting('cancel_partial_refund_pct',  50);

const bookingDate = new Date((booking.date_from || booking.booking_date).split('T')[0] + 'T00:00:00');
const today       = new Date(); today.setHours(0,0,0,0);
const daysUntil   = Math.round((bookingDate - today) / 86400000);

const depositPaid   = parseFloat(booking.deposit_paid  || 0);
const totalPaid     = parseFloat(booking.total_amount  || 0) - parseFloat(booking.balance_due || 0);
const refundableAmt = Math.max(0, totalPaid - depositPaid);
const totalAmt      = parseFloat(booking.total_amount  || 0);
let refundType, refundAmount;

if (input.refund_override !== null) {
  refundAmount = Math.min(Math.max(0, input.refund_override), refundableAmt);
  refundType   = refundAmount >= refundableAmt && refundableAmt > 0 ? 'full' : refundAmount > 0 ? 'partial' : 'none';
} else if (daysUntil >= fullDays) {
  refundType   = 'full';
  refundAmount = refundableAmt;
} else if (daysUntil >= partDays) {
  refundType   = 'partial';
  refundAmount = parseFloat((refundableAmt * partPct / 100).toFixed(2));
} else {
  refundType   = 'none';
  refundAmount = 0;
}

return [{ json: {
  ...input,
  booking,
  daysUntil,
  refundType,
  refundAmount,
  depositPaid,
  totalPaid,
  refundableAmt,
  totalAmt,
  policyApplied: { fullDays, partDays, partPct }
}}];
